"use client";

import { useState } from "react";
import { Upload, FileArchive, BookOpen, Layers, LogOut, Waves, Menu, X, Settings, UserPlus, BarChart3, Stethoscope, Link, MessageSquare, ShieldCheck, Search, Cpu, ActivitySquare } from "lucide-react";

export type ViewType = "new-scan" | "upload" | "reports" | "ai-summary" | "ai-chat" | "learn" | "training" | "analytics" | "scoring" | "ehr-sync" | "patient-search" | "settings";

interface SidebarProps {
    currentView: ViewType;
    onChangeView: (view: ViewType) => void;
}

export function Sidebar({ currentView, onChangeView }: SidebarProps) {
    const [isOpen, setIsOpen] = useState(false);

    const navItems: { id: ViewType; label: string; icon: any }[] = [
        { id: "new-scan", label: "New Scan", icon: UserPlus },
        { id: "upload", label: "Analysis & Upload", icon: Upload },
        { id: "reports", label: "Patient Reports", icon: FileArchive },
        { id: "patient-search", label: "Global Search", icon: Search },
        { id: "ai-summary", label: "AI Summary", icon: Layers },
        { id: "ai-chat", label: "AI Assistant", icon: MessageSquare },
        { id: "learn", label: "Knowledge Hub", icon: BookOpen },
        { id: "training", label: "Training Mode", icon: ActivitySquare },
        { id: "analytics", label: "Analytics", icon: BarChart3 },
        { id: "scoring", label: "Scoring Models", icon: ActivitySquare },
        { id: "ehr-sync", label: "EHR Sync", icon: Link },
        { id: "settings", label: "Settings", icon: Settings },
    ];

    return (
        <>
            <button
                onClick={() => setIsOpen(true)}
                className="fixed top-4 left-4 z-50 p-2 rounded-lg bg-white shadow-sm border border-slate-200 lg:hidden"
            >
                <Menu className="w-5 h-5 text-slate-700" />
            </button>

            {isOpen && (
                <div
                    className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-40 lg:hidden"
                    onClick={() => setIsOpen(false)}
                />
            )}

            <div className={`
                ${isOpen ? 'fixed translate-x-0' : 'fixed -translate-x-full lg:translate-x-0 lg:static'}
                inset-y-0 left-0 z-50 w-72 bg-white border-r border-[#e2e8f0] shadow-sm
                flex flex-col text-[#1a1c29] transition-transform duration-300 ease-in-out h-screen
            `}>
                {/* Header */}
                <div className="h-20 flex items-center justify-between px-6 border-b border-[#e2e8f0]/60">
                    <div className="flex items-center gap-3">
                        <div className="relative">
                            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#1e3a8a] to-[#3b82f6] flex items-center justify-center shadow-md">
                                <Waves className="w-6 h-6 text-white" />
                            </div>
                            <div className="absolute -top-1 -right-1 w-3.5 h-3.5 bg-emerald-500 rounded-full border-2 border-white" />
                        </div>
                        <div>
                            <h1 className="text-xl font-bold bg-gradient-to-r from-[#1e3a8a] to-[#2563eb] bg-clip-text text-transparent">
                                Wavelength
                            </h1>
                            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-semibold">
                                Clinical AI System
                            </p>
                        </div>
                    </div>
                    <button onClick={() => setIsOpen(false)} className="lg:hidden p-2 text-slate-400 hover:text-slate-600">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Navigation */}
                <div className="flex-1 overflow-y-auto overflow-x-hidden scrollbar-thin scrollbar-thumb-slate-200 py-4 hide-scrollbar">
                    <nav className="px-4 space-y-1">
                        {navItems.map((item) => (
                            <button
                                key={item.id}
                                onClick={() => {
                                    onChangeView(item.id);
                                    setIsOpen(false);
                                }}
                                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 font-medium ${currentView === item.id
                                    ? "bg-[#1e3a8a] text-white shadow-sm shadow-blue-900/10"
                                    : "text-slate-600 hover:bg-[#f8fafc] hover:text-[#1e3a8a]"
                                    }`}
                            >
                                <item.icon className={`w-5 h-5 ${currentView === item.id ? "text-blue-200" : "text-slate-400"}`} />
                                <span className="text-sm">{item.label}</span>
                            </button>
                        ))}
                    </nav>
                </div>

                {/* Footer */}
                <div className="p-4 border-t border-[#e2e8f0]/60">
                    <div className="flex items-center gap-3 px-4 py-3 rounded-xl bg-slate-50">
                        <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold text-sm">
                            DR
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold truncate text-slate-700">Dr. Sarah Jenkins</p>
                            <p className="text-xs text-slate-500 truncate">Radiology Dept.</p>
                        </div>
                        <LogOut className="w-4 h-4 text-slate-400 hover:text-slate-600 cursor-pointer" />
                    </div>
                </div>
            </div>
        </>
    );
}

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { FastForward, Presentation, RefreshCw, AlertTriangle } from "lucide-react";
import { getDiseaseProgression } from "@/lib/api";
import ReactMarkdown from "react-markdown";

interface DiseaseTimelineProps {
    topDisease: string;
}

export function DiseaseTimeline({ topDisease }: DiseaseTimelineProps) {
    const [progression, setProgression] = useState<{ stages: { stage: string, url: string }[], explanation: string } | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [selectedStage, setSelectedStage] = useState<number>(0);

    useEffect(() => {
        if (!topDisease || topDisease === "No Finding") return;

        const fetchData = async () => {
            setLoading(true);
            setError(null);
            try {
                const data = await getDiseaseProgression(topDisease);
                if (data.error || data.stages.length === 0) {
                    setError(data.error || "No progression data found.");
                } else {
                    setProgression(data as any);
                }
            } catch (err) {
                setError("Failed to fetch progression data.");
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [topDisease]);

    if (topDisease === "No Finding") return null;

    return (
        <div className="mt-8 rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden flex flex-col">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-violet-100 flex items-center justify-center border border-violet-200 shadow-inner">
                    <FastForward className="w-6 h-6 text-violet-600" />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-slate-900">Disease Progression Timeline</h3>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mt-1">
                        NIH Dataset Precedents ΓÇó {topDisease}
                    </p>
                </div>
            </div>

            <div className="p-6 min-h-[300px] flex items-center justify-center">
                {loading ? (
                    <div className="flex flex-col items-center gap-3">
                        <RefreshCw className="w-8 h-8 text-violet-500 animate-spin" />
                        <span className="text-sm font-medium text-slate-500">Synthesizing timeline from LLaMA-3...</span>
                    </div>
                ) : error ? (
                    <div className="flex flex-col items-center gap-3 text-amber-600">
                        <AlertTriangle className="w-8 h-8 opacity-50" />
                        <span className="text-sm font-medium">Timeline visualization unavailable for {topDisease}</span>
                    </div>
                ) : progression ? (
                    <div className="w-full flex flex-col lg:flex-row gap-8">
                        {/* Image Viewer & Slider */}
                        <div className="flex-1 flex flex-col gap-6">
                            <div className="aspect-[4/3] w-full bg-slate-900 rounded-2xl overflow-hidden relative shadow-inner border border-slate-200">
                                <AnimatePresence mode="wait">
                                    <motion.img
                                        key={selectedStage}
                                        src={progression.stages[selectedStage].url}
                                        initial={{ opacity: 0, scale: 0.95 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        exit={{ opacity: 0, scale: 1.05 }}
                                        transition={{ duration: 0.4 }}
                                        className="w-full h-full object-contain p-2"
                                        alt={`Stage ${selectedStage}`}
                                    />
                                </AnimatePresence>
                                <div className="absolute top-4 right-4 bg-black/60 backdrop-blur-sm px-3 py-1 rounded-full border border-white/20">
                                    <span className="text-xs font-bold text-white tracking-widest uppercase">
                                        {progression.stages[selectedStage].stage} Stage
                                    </span>
                                </div>
                            </div>

                            {/* Slider Controls */}
                            <div className="relative px-4">
                                <div className="absolute top-1/2 left-0 right-0 h-1 bg-slate-200 -translate-y-1/2 rounded-full" />
                                <div className="relative flex justify-between">
                                    {progression.stages.map((stage, idx) => (
                                        <button
                                            key={idx}
                                            onClick={() => setSelectedStage(idx)}
                                            className="flex flex-col items-center gap-3 group focus:outline-none"
                                        >
                                            <div className={`w-6 h-6 rounded-full border-4 flex items-center justify-center transition-all duration-300 z-10 ${selectedStage === idx ? 'bg-violet-600 border-white shadow-[0_0_0_2px_rgba(124,58,237,1)] scale-125' : 'bg-slate-300 border-white shadow-[0_0_0_2px_rgba(203,213,225,1)] group-hover:bg-violet-400'}`} />
                                            <span className={`text-xs font-bold tracking-widest uppercase transition-colors ${selectedStage === idx ? 'text-violet-700' : 'text-slate-400 group-hover:text-violet-500'}`}>
                                                {stage.stage}
                                            </span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* AI Explanation Panel */}
                        <div className="w-full lg:w-80 shrink-0 bg-violet-50/50 rounded-2xl p-6 border border-violet-100 shadow-sm relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                                <Presentation className="w-24 h-24 text-violet-900" />
                            </div>
                            <div className="flex items-center gap-2 mb-4 relative z-10">
                                <div className="w-6 h-6 rounded bg-violet-600 flex items-center justify-center">
                                    <span className="text-[10px] font-bold text-white">AI</span>
                                </div>
                                <span className="text-xs font-bold text-violet-900 uppercase tracking-widest">
                                    Clinical Summary
                                </span>
                            </div>
                            <div className="prose prose-sm prose-violet prose-p:leading-relaxed text-slate-700 font-medium relative z-10">
                                <ReactMarkdown>{progression.explanation}</ReactMarkdown>
                            </div>
                        </div>
                    </div>
                ) : null}
            </div>
        </div>
    );
}

import { motion, AnimatePresence } from "framer-motion";
import { X, Info, ShieldCheck, Database, GitBranch, Cpu, AlertTriangle, Image as ImageIcon } from "lucide-react";
import type { Justification } from "@/types";

interface JustificationModalProps {
    isOpen: boolean;
    onClose: () => void;
    disease: string;
    probability: number;
    justification: Justification | null;
}

export function JustificationModal({ isOpen, onClose, disease, probability, justification }: JustificationModalProps) {
    if (!isOpen || !justification) return null;

    return (
        <AnimatePresence>
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                {/* Backdrop */}
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={onClose}
                    className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
                />

                {/* Modal */}
                <motion.div
                    initial={{ opacity: 0, scale: 0.95, y: 20 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.95, y: 20 }}
                    className="relative w-full max-w-2xl bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden"
                >
                    {/* Header */}
                    <div className="px-6 py-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-indigo-100 flex items-center justify-center border border-indigo-200">
                                <ShieldCheck className="w-5 h-5 text-indigo-600" />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-slate-900 tracking-tight">AI Clinical Justification</h3>
                                <p className="text-xs font-medium text-slate-500 uppercase tracking-wider">Unassailable Evidence Engine</p>
                            </div>
                        </div>
                        <button
                            onClick={onClose}
                            className="p-2 rounded-full hover:bg-slate-200 text-slate-400 hover:text-slate-600 transition-colors"
                        >
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <div className="p-6 space-y-6">

                        {/* Top Stat Row */}
                        <div className="flex items-center justify-between p-4 rounded-2xl bg-gradient-to-br from-slate-50 to-slate-100 border border-slate-200">
                            <div>
                                <p className="text-sm font-bold text-slate-500 mb-1">Target Pathology</p>
                                <p className="text-2xl font-black text-slate-900">{disease}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-500 mb-1">Ensemble Confidence</p>
                                <div className="flex items-end gap-2 justify-end">
                                    <span className={`text-3xl font-black ${probability > 0.7 ? 'text-rose-600' : probability > 0.4 ? 'text-amber-500' : 'text-emerald-500'}`}>
                                        {(probability * 100).toFixed(1)}%
                                    </span>
                                    <span className="text-sm font-bold text-slate-400 mb-1.5">{justification.confidence_interval}</span>
                                </div>
                            </div>
                        </div>

                        {/* Primary Evidence */}
                        <div>
                            <div className="flex items-center gap-2 mb-3">
                                <Info className="w-4 h-4 text-blue-500" />
                                <h4 className="font-bold text-slate-900">Primary Radiological Evidence</h4>
                            </div>
                            <div className="p-4 rounded-xl bg-blue-50/50 border border-blue-100 text-blue-900 text-sm leading-relaxed font-medium">
                                "{justification.primary_evidence}"
                            </div>
                        </div>

                        {/* Grid for Technical Details */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {/* Training Data */}
                            <div className="p-4 rounded-xl border border-slate-200 bg-white">
                                <div className="flex items-center gap-2 mb-2">
                                    <Database className="w-4 h-4 text-purple-500" />
                                    <h5 className="font-bold text-slate-800 text-sm">Dataset Origin</h5>
                                </div>
                                <p className="text-xs text-slate-500 leading-relaxed font-medium">
                                    {justification.dataset_origin}
                                </p>
                            </div>

                            {/* Model Algo */}
                            <div className="p-4 rounded-xl border border-slate-200 bg-white">
                                <div className="flex items-center gap-2 mb-2">
                                    <GitBranch className="w-4 h-4 text-emerald-500" />
                                    <h5 className="font-bold text-slate-800 text-sm">Threshold Calibration</h5>
                                </div>
                                <p className="text-xs text-slate-500 leading-relaxed font-medium">
                                    {justification.threshold_calibration}
                                </p>
                            </div>
                        </div>

                        {/* Similar Historical Cases (Proof) */}
                        {justification.reference_images && justification.reference_images.length > 0 && (
                            <div>
                                <div className="flex items-center gap-2 mb-3">
                                    <ImageIcon className="w-4 h-4 text-slate-700" />
                                    <h4 className="font-bold text-slate-900">Similar Verified Cases (Dataset Proof)</h4>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {justification.reference_images.map((img, idx) => (
                                        <div key={idx} className="relative rounded-xl overflow-hidden border border-slate-200 group bg-slate-900">
                                            <div className="aspect-[4/3] w-full relative">
                                                {/* eslint-disable-next-line @next/next/no-img-element */}
                                                <img
                                                    src={img.url}
                                                    alt={img.caption}
                                                    className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-300"
                                                />
                                                {/* Overlay Gradient */}
                                                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none" />
                                            </div>
                                            <div className="absolute bottom-0 left-0 right-0 p-3">
                                                <p className="text-xs text-white font-medium leading-tight">
                                                    {img.caption}
                                                </p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Disclaimer */}
                        <div className="flex items-start gap-3 p-4 bg-amber-50 rounded-xl border border-amber-200">
                            <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                            <p className="text-xs text-amber-800 font-medium leading-relaxed">
                                Calculations derived via aggregated soft-voting of independently trained DenseNet & EfficientNet CNN architectures. AI predictions augment, but do not replace, formal radiologist review.
                            </p>
                        </div>

                    </div>
                </motion.div>
            </div>
        </AnimatePresence>
    );
}

import { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { Send, Bot, User, Database, Cpu, Activity, ShieldCheck, Sparkles, Loader2 } from "lucide-react";
import { sendChatMessage } from "@/lib/api";
import ReactMarkdown from "react-markdown";

interface Message {
  role: "user" | "assistant";
  content: string;
}

export function AiChat() {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content: "Hello Dr. Jenkins. I am Wavelength's Global AI Assistant powered by LLaMA-3. I have full access to our local NIH curated dataset containing 112,000+ patient records, as well as the active DenseNet classification models. How can I assist your clinical workflow today?"
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { role: "user", content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput("");
    setIsLoading(true);

    try {
      // Pass the previous messages (up to a limit if we wanted) as history
      const history = messages.map(m => ({ role: m.role, content: m.content }));
      const response = await sendChatMessage(userMsg.content, history);
      
      setMessages(prev => [...prev, { role: "assistant", content: response.reply }]);
    } catch (e) {
      setMessages(prev => [...prev, { 
        role: "assistant", 
        content: "I'm currently unable to connect to the LLM backend. Please check if the Ollama service is running." 
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] w-full max-w-5xl mx-auto rounded-3xl border border-slate-200 bg-white shadow-sm overflow-hidden relative">
      <div className="absolute top-0 right-0 p-8 opacity-5">
        <Sparkles className="w-64 h-64 text-blue-900" />
      </div>

      {/* Header */}
      <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between bg-white relative z-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg shadow-blue-500/20 relative">
            <Bot className="w-6 h-6 text-white" />
            <div className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 border-2 border-white" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Global Clinical Assistant</h2>
            <div className="flex flex-wrap items-center gap-3 text-xs font-bold uppercase tracking-wider text-slate-500 mt-1">
              <span className="flex items-center gap-1"><Cpu className="w-3 h-3 text-indigo-500" /> LLaMA-3 8B</span>
              <span className="flex items-center gap-1"><Database className="w-3 h-3 text-emerald-500" /> NIH Curated Data</span>
              <span className="flex items-center gap-1"><ShieldCheck className="w-3 h-3 text-blue-500" /> HIPAA Compliant Local Secure</span>
            </div>
          </div>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-full">
            <Activity className="w-4 h-4 text-emerald-500 animate-pulse" />
            <span className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">Active Runtime</span>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/50 relative z-10 hide-scrollbar">
        {messages.map((msg, idx) => (
          <motion.div 
            key={idx}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className={`flex w-full ${msg.role === "user" ? "justify-end" : "justify-start"}`}
          >
            <div className={`flex gap-4 max-w-[80%] ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
              {/* Avatar */}
              <div className="shrink-0">
                {msg.role === "assistant" ? (
                  <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-blue-600 flex items-center justify-center shadow-md">
                    <Bot className="w-5 h-5 text-white" />
                  </div>
                ) : (
                  <div className="w-10 h-10 rounded-xl bg-slate-200 flex items-center justify-center border border-slate-300">
                    <User className="w-5 h-5 text-slate-600" />
                  </div>
                )}
              </div>

              {/* Message Bubble */}
              <div className={`
                p-5 rounded-2xl text-sm leading-relaxed shadow-sm
                ${msg.role === "user" 
                  ? "bg-slate-900 text-white rounded-tr-none" 
                  : "bg-white border border-slate-200 text-slate-800 rounded-tl-none"}
              `}>
                {msg.role === "assistant" ? (
                    <div className="prose prose-sm max-w-none prose-p:mb-3 prose-p:leading-relaxed prose-strong:text-indigo-900 prose-strong:font-bold prose-ul:my-2 prose-li:my-0 text-slate-800">
                        <ReactMarkdown>{msg.content}</ReactMarkdown>
                    </div>
                ) : (
                    <div className="whitespace-pre-wrap">{msg.content}</div>
                )}
              </div>
            </div>
          </motion.div>
        ))}
        {isLoading && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                <div className="flex gap-4 max-w-[80%]">
                    <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-blue-600 flex items-center justify-center shadow-md shrink-0">
                        <Bot className="w-5 h-5 text-white" />
                    </div>
                    <div className="p-5 rounded-2xl rounded-tl-none bg-white border border-slate-200 shadow-sm flex items-center gap-3">
                        <Loader2 className="w-5 h-5 text-indigo-500 animate-spin" />
                        <span className="text-sm font-medium text-slate-500">Synthesizing clinical response...</span>
                    </div>
                </div>
            </motion.div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-6 bg-white border-t border-slate-100 relative z-10">
        <form 
          onSubmit={(e) => { e.preventDefault(); handleSend(); }}
          className="relative flex items-end gap-3"
        >
          <div className="relative flex-1 bg-slate-50 border border-slate-200 rounded-2xl overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 focus-within:border-indigo-500 transition-all shadow-sm">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder="Ask about patient records, diagnostic models, or dataset statistics..."
              className="w-full bg-transparent p-4 outline-none resize-none min-h-[60px] max-h-[200px] text-sm text-slate-700 placeholder:text-slate-400"
              rows={1}
            />
          </div>
          <button 
            type="submit"
            disabled={!input.trim() || isLoading}
            className="w-[60px] h-[60px] rounded-2xl bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white flex items-center justify-center transition-colors shadow-md shadow-indigo-500/20 shrink-0"
          >
            <Send className="w-5 h-5 ml-1" />
          </button>
        </form>
        <p className="text-center mt-3 text-[10px] uppercase tracking-widest font-bold text-slate-400">
          Wavelength AI responses are generated locally. No patient data leaves this environment.
        </p>
      </div>
    </div>
  );
}

